"""Add real eight-month historical verification and live fusion readiness to existing HAB app.

Preserves existing React/FastAPI, satellite pipeline, XGBoost and replay.
Run from the root of HAB_Risk_Forecasting: python enable_real_8month_verification.py
"""
from pathlib import Path
import base64
import gzip
import hashlib
import shutil
import subprocess
import sys

root=Path.cwd()
api=root/'backend/ml_api.py'
forecast=root/'frontend/src/pages/Forecast.jsx'
auto=root/'backend/auto_forecast.py'
for item in (api,forecast,auto):
    if not item.exists():
        raise SystemExit(f'Required existing file missing: {item}')

source_csv=gzip.decompress(base64.b64decode(''))
expected_hash='6b2cb6209b5c2dfa5669a895262a8cdb845c2e441f13cff06e27ff8520b5b107'
assert hashlib.sha256(source_csv).hexdigest()==expected_hash, 'Dataset checksum failed'

historical_code='"""Reproducible prospective-style 2021 out-of-time bloom-proxy benchmark.\n\nReal source: historical station-month chlorophyll and water quality from the\nuser-provided Water Atlas-derived Lake Okeechobee CSV (2019-2021).\nAll output labels are explicitly proxies based on the supplied 40 ug/L\nchlorophyll threshold. This is not a satellite-fusion or HAB-toxicity test.\n\nRun: python backend/historical_backtest.py\n"""\nimport csv\nimport json\nfrom collections import Counter\nfrom datetime import datetime\nfrom pathlib import Path\n\nimport numpy as np\nfrom sklearn.metrics import accuracy_score, precision_score, recall_score, f1_score, confusion_matrix\nfrom xgboost import XGBClassifier\n\nROOT = Path(__file__).resolve().parent.parent\nSRC = ROOT / \'backend/data/lake_okeechobee_station_month_2019_2021.csv\'\nOUT = ROOT / \'frontend/public/historical_backtest_2021.json\'\nMODEL_OUT = ROOT / \'backend/models/xgb_insitu_trend_baseline.json\'\nPARAMS = (\'temperature_c_median\',\'pH_median\',\'DO_mg_l_median\')\nFEATURE_NAMES = [f\'{k}_t\' for k in PARAMS] + [f\'{k}_prev\' for k in PARAMS] + [f\'{k}_delta\' for k in PARAMS]\n\n\ndef month_next(m):\n    d=datetime.strptime(m, \'%Y-%m\')\n    y = d.year + (d.month == 12)\n    m2 = (d.month % 12) + 1\n    return f\'{y:04}-{m2:02}\'\n\n\ndef load():\n    with SRC.open(newline=\'\',encoding=\'utf-8-sig\') as f:\n        data=list(csv.DictReader(f))\n    by_station={}\n    for r in data:\n        by_station.setdefault(r[\'station_id\'], {})[r[\'month\']] = r\n    examples=[]\n    for sid,months in by_station.items():\n        for m, row in months.items():\n            prev = months.get(next((p for p in months if month_next(p)==m), \'\'))\n            following = months.get(month_next(m))\n            if prev is None or following is None:\n                continue\n            try:\n                cur = [float(row[k]) for k in PARAMS]\n                old = [float(prev[k]) for k in PARAMS]\n                target = int(following[\'observed_bloom_proxy_event_40ug_l\'])\n                if target not in (0,1): continue\n                features = cur + old + [a-b for a,b in zip(cur,old)]\n                if not np.isfinite(features).all(): continue\n            except (ValueError, KeyError, TypeError):\n                continue\n            examples.append({\'station_id\':sid,\'input_month\':m,\'target_month\':month_next(m),\n                             \'features\':features,\'actual\':target,\n                             \'actual_next_month_chlorophyll_ug_l\':float(following[\'insitu_chl_a_ug_l_median\']),\n                             \'actual_next_month_chlorophyll_max_ug_l\':float(following[\'insitu_chl_a_ug_l_max\']),\n                             \'current_inputs\':dict(zip(PARAMS, cur)),\n                             \'monthly_delta\':dict(zip(PARAMS,[a-b for a,b in zip(cur,old)]))})\n    return data, sorted(examples,key=lambda x:(x[\'target_month\'],x[\'station_id\']))\n\n\ndef main():\n    original,examples=load()\n    train=[x for x in examples if x[\'target_month\'] < \'2021-01\']\n    test=[x for x in examples if \'2021-01\'<=x[\'target_month\']<=\'2021-12\']\n    assert train and test, \'Not enough historical data\'\n    ytr = np.asarray([x[\'actual\'] for x in train])\n    yte = np.asarray([x[\'actual\'] for x in test])\n    print(\'Source rows:\', len(original), \'Train pairs:\',len(train),\'Test pairs:\',len(test))\n    print(\'Training positives:\',int(ytr.sum()),\'Test positives:\',int(yte.sum()))\n    if len(set(ytr))<2:\n        raise SystemExit(\'Training set only contains one class; evaluation unavailable\')\n    ratio = float((ytr==0).sum()/max(1,(ytr==1).sum()))\n    model=XGBClassifier(n_estimators=100,max_depth=2,learning_rate=0.04,\n                        min_child_weight=2, subsample=0.9,colsample_bytree=0.9,\n                        reg_lambda=5,scale_pos_weight=ratio,\n                        eval_metric=\'logloss\',random_state=42,n_jobs=1)\n    model.fit(np.asarray([x[\'features\'] for x in train]), ytr)\n    probs=model.predict_proba(np.asarray([x[\'features\'] for x in test]))[:,1]\n    pred=(probs>=0.5).astype(int)\n    baseline=np.zeros_like(yte)\n    def metrics(yhat):\n        tn,fp,fn,tp=[int(v) for v in confusion_matrix(yte,yhat,labels=[0,1]).ravel()]\n        return {\'accuracy\':round(float(accuracy_score(yte,yhat)),4),\n                \'precision\':round(float(precision_score(yte,yhat,zero_division=0)),4),\n                \'recall\':round(float(recall_score(yte,yhat,zero_division=0)),4),\n                \'f1\':round(float(f1_score(yte,yhat,zero_division=0)),4),\n                \'correct\':int((yhat==yte).sum()),\'total\':len(yte),\n                \'confusion\':{\'TN\':tn,\'FP\':fp,\'FN\':fn,\'TP\':tp}}\n    rows=[]\n    for item,p,yhat in zip(test,probs,pred):\n        rows.append({**{k:v for k,v in item.items() if k!=\'features\'},\n                     \'probability\':round(float(p),4),\'predicted\':int(yhat),\n                     \'correct\':bool(yhat==item[\'actual\'])})\n    eight={}\n    for station in sorted({r[\'station_id\'] for r in rows}):\n        station_rows=[r for r in rows if r[\'station_id\']==station][:8]\n        eight[station]=station_rows\n    payload={\n        \'dataset\':\'Lake Okeechobee Water Atlas-derived historical station-month observations (2019-2021)\',\n        \'test_type\':\'REAL_HISTORICAL_INSITU_ONLY_NEXT_MONTH_PROXY_BACKTEST\',\n        \'split\':\'Train target months up to December 2020; held-out target months January-December 2021\',\n        \'model\':\'Separate XGBoost sensor-trend baseline, NOT the saved five-feature satellite-fusion model\',\n        \'target\':\'Following-month maximum in-situ chlorophyll-a >= 40 ug/L; proxy event only, not toxicity or verified HAB\',\n        \'real_satellite_used\':False,\n        \'time_features\':FEATURE_NAMES,\n        \'source_rows\':len(original), \'training_examples\':len(train), \'test_examples\':len(test),\n        \'training_positives\':int(ytr.sum()),\'test_positives\':int(yte.sum()),\n        \'metrics\':metrics(pred),\'always_no_bloom_baseline\':metrics(baseline),\n        \'eight_month_by_station\':eight,\n        \'all_test_results\':rows,\n        \'limitations\':[\'Only a chlorophyll-based proxy; not verified harmful blooms\',\n                       \'Historical Okeechobee satellite feature values absent; do not claim satellite-fusion validation\',\n                       \'Potential station-level dependence and small positive class; results preliminary\',\n                       \'No Laguna de Bay model accuracy implied\']}\n    OUT.parent.mkdir(parents=True,exist_ok=True)\n    MODEL_OUT.parent.mkdir(parents=True,exist_ok=True)\n    OUT.write_text(json.dumps(payload,indent=2),encoding=\'utf-8\')\n    model.save_model(MODEL_OUT)\n    print(\'Model\', payload[\'metrics\'])\n    print(\'Always-negative\',payload[\'always_no_bloom_baseline\'])\n    for s in sorted(eight):\n        print(\'station\',s,\':\',[(x[\'target_month\'],x[\'correct\']) for x in eight[s]])\n    print(\'Report:\',OUT,\'Model:\',MODEL_OUT)\n\nif __name__==\'__main__\': main()\n'
historical_panel='import React, { useEffect, useState } from \'react\';\n\nconst pct = (v) => `${(100 * Number(v || 0)).toFixed(1)}%`;\nconst yName = (v) => Number(v) === 1 ? \'BLOOM PROXY\' : \'NO BLOOM PROXY\';\nconst cell = { padding: \'9px 11px\', borderBottom: \'1px solid #e6ece8\', textAlign: \'left\', verticalAlign: \'top\' };\n\nexport default function HistoricalBacktestPanel() {\n  const [report, setReport] = useState(null);\n  const [station, setStation] = useState(\'17625\');\n  const [error, setError] = useState(\'\');\n  useEffect(() => {\n    fetch(\'/historical_backtest_2021.json\')\n      .then(async r => {\n        if (!r.ok) throw new Error(\'Historical report not installed. Run python backend/historical_backtest.py.\');\n        return await r.json();\n      })\n      .then(setReport)\n      .catch(e => setError(e.message));\n  }, []);\n  const stations = Object.keys(report?.eight_month_by_station || {}).sort();\n  const selectedStation = stations.includes(station) ? station : stations[0];\n  const rows = report?.eight_month_by_station?.[selectedStation] || [];\n  const hits = rows.filter(row => row.correct).length;\n  return (\n    <section style={{ background:\'#fff\', border:\'1px solid #d8e3da\', borderRadius:12,\n                      padding:20, margin:\'14px 0 20px\' }}>\n      <h2 style={{ marginTop:0 }}>8-Month Historical Verification</h2>\n      <p style={{ fontSize:13, color:\'#895500\' }}>\n        <b>REAL OKEECHOBEE HISTORICAL DATA, NOT LAGUNA SATELLITE-FUSION VALIDATION.</b>\n        {\' \'}Separate XGBoost baseline uses monthly in-situ temperature, pH, DO,\n        previous-month readings and their changes to predict next-month bloom-proxy occurrence.\n        The label is based on next-month maximum observed chlorophyll-a ≥ 40 µg/L;\n        it does not establish HAB toxins or confirmed harmful blooms.\n      </p>\n      {error && <p style={{ color:\'#aa1822\' }}>Error: {error}</p>}\n      {!report && !error && <p>Loading reproducible historical backtest...</p>}\n      {report && <>\n        <div style={{ display:\'flex\', flexWrap:\'wrap\', gap:18, padding:\'12px 0\' }}>\n          <div><b>{report.metrics.correct}/{report.metrics.total}</b><div style={{ fontSize:12 }}>Correct overall</div></div>\n          <div><b>{pct(report.metrics.accuracy)}</b><div style={{ fontSize:12 }}>Model accuracy</div></div>\n          <div><b>{pct(report.metrics.recall)}</b><div style={{ fontSize:12 }}>Positive recall</div></div>\n          <div><b>{pct(report.always_no_bloom_baseline.accuracy)}</b><div style={{ fontSize:12 }}>Always NO_BLOOM baseline</div></div>\n        </div>\n        <p style={{ fontSize:12, color:\'#895500\' }}>\n          Training: {report.training_examples} monthly pairs ending by 2020;\n          unseen evaluation: {report.test_examples} monthly pairs in 2021.\n          The model is <b>below the always-negative accuracy baseline</b> and needs improvement.\n          Positive events in held-out data: {report.test_positives}.\n        </p>\n        <div style={{ display:\'flex\', alignItems:\'center\', gap:12, flexWrap:\'wrap\', marginTop:12 }}>\n          <label htmlFor="historical-station"><b>Monitoring station</b></label>\n          <select id="historical-station" value={selectedStation || \'\'}\n            onChange={e => setStation(e.target.value)}\n            style={{ padding:9, border:\'1px solid #ccd8d0\', borderRadius:8 }}>\n            {stations.map(id => <option value={id} key={id}>{id}</option>)}\n          </select>\n          <span style={{ fontSize:13 }}>\n            <b>{hits}/{rows.length} HIT</b> for this eight-month station view\n          </span>\n        </div>\n        <div style={{ overflowX:\'auto\', marginTop:12 }}>\n          <table style={{ width:\'100%\', borderCollapse:\'collapse\', fontSize:13 }}>\n            <thead><tr>\n              {[\'Input month\',\'Forecast month\',\'P(bloom)\',\'Model predicts\',\'Observed next month\',\'Maximum Chl-a (µg/L)\',\'Verdict\'].map(k =>\n                <th key={k} style={{ ...cell, background:\'#f4f7f5\' }}>{k}</th>)}\n            </tr></thead>\n            <tbody>{rows.map(r => <tr key={r.target_month + r.station_id}>\n              <td style={cell}>{r.input_month}</td>\n              <td style={cell}><b>{r.target_month}</b></td>\n              <td style={cell}>{pct(r.probability)}</td>\n              <td style={cell}>{yName(r.predicted)}</td>\n              <td style={cell}>{yName(r.actual)}</td>\n              <td style={cell}>{Number(r.actual_next_month_chlorophyll_max_ug_l).toFixed(2)}</td>\n              <td style={{...cell, fontWeight:700, color:r.correct ? \'#19704b\' : \'#b42318\'}}>\n                {r.correct ? \'HIT\' : \'MISS\'}\n              </td>\n            </tr>)}</tbody>\n          </table>\n        </div>\n        <p style={{ fontSize:12, color:\'#647069\', marginBottom:0 }}>\n          Preselected chronological test data; no month was selected for whether its prediction was right.\n          Source: user-provided 2019–2021 Water Atlas-derived Okeechobee measurements.\n          This backtest excludes satellite features because matching historical satellite values were unavailable.\n          It is separate from the existing five-input XGBoost fusion demo.\n        </p>\n      </>}\n    </section>\n  );\n}\n'
live_panel='import React, { useEffect, useState } from \'react\';\nimport { collection, onSnapshot, query, where } from \'firebase/firestore\';\nimport { db } from \'../firebase\';\n\nconst fields = [\n  [\'temperatureC\',\'Water temperature\',\'°C\'],\n  [\'pH\',\'pH\',\'\'],\n  [\'dissolvedOxygenMgL\',\'Dissolved oxygen\',\'mg/L\'],\n];\nfunction previousMonth(month) {\n  if (!/^\\d{4}-(0[1-9]|1[0-2])$/.test(month)) return \'\';\n  const [y,m] = month.split(\'-\').map(Number);\n  return m === 1 ? `${y-1}-12` : `${y}-${String(m-1).padStart(2,\'0\')}`;\n}\nfunction median(xs) {\n  const vals = xs.filter(Number.isFinite).sort((a,b)=>a-b);\n  if (!vals.length) return null;\n  const n=Math.floor(vals.length/2);\n  return vals.length%2 ? vals[n] : (vals[n-1]+vals[n])/2;\n}\nfunction medians(readings) {\n  const fromDevice=readings.filter(r =>\n    r.sourceType === \'DEVICE_REPORTED_UNVERIFIED\' && r.isSimulated !== true);\n  const obj={ count:fromDevice.length };\n  for (const [key] of fields) obj[key]=median(fromDevice.map(r=>r[key] == null ? NaN : Number(r[key])));\n  return obj;\n}\nconst fmt=v=>Number.isFinite(v)?Number(v).toFixed(2):\'Missing\';\n\nexport default function LiveFusionPanel() {\n  const [month,setMonth]=useState(\'2024-01\');\n  const [current,setCurrent]=useState([]);\n  const [previous,setPrevious]=useState([]);\n  const [satellites,setSatellites]=useState([]);\n  const [error,setError]=useState(\'\');\n  useEffect(()=>{\n    setCurrent([]);setPrevious([]);setError(\'\');\n    const unsubs=[];\n    const watch=(q,setter)=>onSnapshot(q,s=>setter(s.docs.map(d=>d.data())),e=>setError(e.message));\n    unsubs.push(watch(query(collection(db,\'sensor_readings\'),where(\'month\',\'==\',month)),setCurrent));\n    unsubs.push(watch(query(collection(db,\'sensor_readings\'),where(\'month\',\'==\',previousMonth(month))),setPrevious));\n    unsubs.push(watch(query(collection(db,\'satellite_monthly\'),where(\'month\',\'==\',month)),setSatellites));\n    return ()=>unsubs.forEach(fn=>fn());\n  },[month]);\n  const curr=medians(current), prev=medians(previous);\n  const satellite=satellites.find(s=>s.satellite_chl_monthly_median!=null &&\n    s.validAcquisitions>0);\n  const ready=curr.count>0 && prev.count>0 && Boolean(satellite);\n  return <section style={{background:\'#fff\',border:\'1px solid #d8e3da\',borderRadius:12,\n                           padding:20,margin:\'14px 0 20px\'}}>\n    <h2 style={{marginTop:0}}>Live Device + Satellite Fusion Preview</h2>\n    <p style={{fontSize:13}}>\n      Automatically reads <b>genuine device-reported</b> Firestore observations,\n      calculates monthly medians and changes from the previous month,\n      and matches <b>the same calendar month</b> with Sentinel-3 data.\n      Simulated replay readings are excluded. This prepares model inputs but does not\n      claim a validated Laguna forecast.\n    </p>\n    <label>Observation month{\' \'}\n      <input type="month" value={month} onChange={e=>setMonth(e.target.value)} />\n    </label>\n    {error && <p style={{color:\'#b42318\'}}>Firestore read error: {error}</p>}\n    <p>Real device readings: <b>{curr.count}</b> this month; <b>{prev.count}</b> previous month.\n      {\' \'}Satellite matching acquisition: <b>{satellite ? \'Present\' : \'Missing\'}</b></p>\n    <div style={{overflowX:\'auto\'}}><table style={{width:\'100%\',fontSize:13,borderCollapse:\'collapse\'}}>\n      <thead><tr>{[\'Input\',\'Current median\',\'Previous median\',\'Change\'].map(h=><th key={h}\n        style={{padding:10,borderBottom:\'1px solid #ddd\',textAlign:\'left\'}}>{h}</th>)}</tr></thead>\n      <tbody>{fields.map(([key,label,unit]) => <tr key={key}>\n        <td style={{padding:10}}>{label} {unit}</td>\n        <td style={{padding:10}}>{fmt(curr[key])}</td>\n        <td style={{padding:10}}>{fmt(prev[key])}</td>\n        <td style={{padding:10}}>{fmt(Number.isFinite(curr[key]) && Number.isFinite(prev[key])\n          ? curr[key]-prev[key]:null)}</td>\n      </tr>)}</tbody>\n    </table></div>\n    <p>Same-month satellite CHL_NN candidate: <b>{satellite\n      ? `${fmt(Number(satellite.satellite_chl_monthly_median))} µg/L` : \'No qualifying monthly record\'}</b></p>\n    <p style={{fontSize:13,color:ready?\'#176c49\':\'#895500\'}}>\n      <b>{ready ? \'Inputs fused for technical preview.\' : \'Waiting for matching device history and/or satellite data.\'}</b>\n      {\' \'}No automatic next-month Laguna prediction until a trend+satellite model is trained and validated.\n      The existing experimental Lake Okeechobee five-feature model does not consume these trend fields.\n    </p>\n  </section>;\n}\n'
ingestion_code='"""Protected endpoint for genuine ESP32/IoT device readings.\n\nTo use, configure HAB_DEVICE_INGEST_TOKEN as a server-side Codespaces secret.\nThis doesn\'t make a private Codespaces port internet-accessible to an ESP32;\nactual field deployment needs a reachable, secured HTTPS service.\n"""\nimport hashlib\nimport hmac\nimport os\nfrom datetime import datetime, timedelta, timezone\nfrom typing import Optional\n\nfrom fastapi import Header, HTTPException\nfrom pydantic import BaseModel, Field\nfrom backend.auto_forecast import get_database\n\nclass DeviceReading(BaseModel):\n    device_id: str = Field(min_length=2, max_length=64, pattern=r\'^[A-Za-z0-9_-]+$\')\n    observed_at: datetime\n    temperature_c: float = Field(ge=0, le=60)\n    ph: float = Field(ge=0, le=14)\n    dissolved_oxygen_mg_l: float = Field(ge=0, le=30)\n\n\ndef ingest_device_reading(reading: DeviceReading, x_device_token: Optional[str] = Header(default=None)):\n    expected = os.getenv(\'HAB_DEVICE_INGEST_TOKEN\', \'\')\n    if not expected:\n        raise HTTPException(503, \'Device ingestion disabled; configure HAB_DEVICE_INGEST_TOKEN\')\n    if not x_device_token or not hmac.compare_digest(expected, x_device_token):\n        raise HTTPException(401, \'Invalid device credentials\')\n    if reading.observed_at.tzinfo is None:\n        raise HTTPException(422, \'observed_at must include time-zone offset\')\n    dt=reading.observed_at.astimezone(timezone.utc)\n    if dt > datetime.now(timezone.utc) + timedelta(minutes=10):\n        raise HTTPException(422, \'Future observation timestamp\')\n    month=dt.strftime(\'%Y-%m\')\n    safe_id=hashlib.sha256(f\'{reading.device_id}:{dt.isoformat()}\'.encode(\'utf-8\')).hexdigest()\n    db=get_database()\n    db.collection(\'sensor_readings\').document(safe_id).set({\n        \'month\':month,\n        \'deviceId\':reading.device_id,\n        \'timestamp\':dt,\n        \'temperatureC\':reading.temperature_c,\n        \'pH\':reading.ph,\n        \'dissolvedOxygenMgL\':reading.dissolved_oxygen_mg_l,\n        \'sourceType\':\'DEVICE_REPORTED_UNVERIFIED\',\n        \'isSimulated\':False,\n        \'ingestedAt\':datetime.now(timezone.utc),\n    })\n    return {\'accepted\':True,\'month\':month,\'reading_id\':safe_id,\n            \'note\':\'Stored as device-reported, not independently calibrated or verified\'}\n'

existing_api=api.read_text(encoding='utf-8')
existing_forecast=forecast.read_text(encoding='utf-8')

# Append only the protected device ingestion route; preserve all existing routes.
route_marker='PROTECTED_ESP32_DEVICE_INGEST_V1'
if route_marker not in existing_api:
    revised_api=existing_api+"""
# PROTECTED_ESP32_DEVICE_INGEST_V1
from backend.insitu_ingest import ingest_device_reading
app.add_api_route(
    '/api/insitu/reading', ingest_device_reading, methods=['POST'],
    tags=['In-situ hardware ingestion'])
"""
else:
    revised_api=existing_api

# Insert panels into the existing Forecast.jsx wrapper without replacing it.
if 'HistoricalBacktestPanel' not in existing_forecast:
    if '<DemoPipelinePanel />' in existing_forecast:
        target='<DemoPipelinePanel />'
    elif '<AutoForecastPanel />' in existing_forecast:
        target='<AutoForecastPanel />'
    else:
        raise SystemExit('Expected Forecast JSX insertion point not found. No files changed.')
    import_lines=("import HistoricalBacktestPanel from './HistoricalBacktestPanel.jsx';\n"
                  "import LiveFusionPanel from './LiveFusionPanel.jsx';\n")
    revised_forecast=import_lines+existing_forecast
    revised_forecast=revised_forecast.replace(target,
        target+'\n    <LiveFusionPanel />\n    <HistoricalBacktestPanel />',1)
else:
    revised_forecast=existing_forecast

vite=root/'frontend/vite.config.js'
if not vite.exists():
    raise SystemExit('Missing frontend/vite.config.js')

compile(revised_api,str(api),'exec')
compile(historical_code,'backend/historical_backtest.py','exec')
compile(ingestion_code,'backend/insitu_ingest.py','exec')

paths={
    root/'backend/historical_backtest.py':historical_code,
    root/'backend/insitu_ingest.py':ingestion_code,
    root/'frontend/src/pages/HistoricalBacktestPanel.jsx':historical_panel,
    root/'frontend/src/pages/LiveFusionPanel.jsx':live_panel,
}
for path,content in paths.items():
    path.parent.mkdir(parents=True,exist_ok=True)
    if path.exists() and path.read_text(encoding='utf-8')!=content:
        shutil.copy2(path,str(path)+'.pre_8month_verification.bak')
    path.write_text(content,encoding='utf-8')

csv_path=root/'backend/data/lake_okeechobee_station_month_2019_2021.csv'
csv_path.parent.mkdir(parents=True,exist_ok=True)
if csv_path.exists():
    if csv_path.read_bytes()!=source_csv:
        raise SystemExit('Existing historical dataset differs; stop rather than overwrite')
else:
    csv_path.write_bytes(source_csv)

if existing_api!=revised_api:
    shutil.copy2(api,str(api)+'.pre_8month_verification.bak')
    api.write_text(revised_api,encoding='utf-8')
if existing_forecast!=revised_forecast:
    shutil.copy2(forecast,str(forecast)+'.pre_8month_verification.bak')
    forecast.write_text(revised_forecast,encoding='utf-8')

print('Project files updated. Training separate historical sensor-trend baseline...')
subprocess.run([sys.executable,'backend/historical_backtest.py'],check=True)
print('\nINSTALLED: historical eight-month HIT/MISS panel + live in-situ fusion readiness panel.')
print('Protected device endpoint /api/insitu/reading disabled until HAB_DEVICE_INGEST_TOKEN is set.')
print('Existing XGBoost model and Laguna satellite flow were NOT modified.')
print('Restart Vite to see the historical table, restart FastAPI to register device endpoint.')
